styles:
html.w-mod-js:not(.w-mod-ix3) :is(.primary-button .text-button, .primary-button .text-button-hide, .ta1, .bloc100.flex-col.extand.max-w-global.footer *, .ta2) {visibility: hidden !important;}

/* --- FAQ item container --- */
.faq-item {
  cursor: pointer;
}

/* --- Reveal content: hauteur "auto" animée via grid-template-rows --- */
.faq-reveal-content {
  display: grid;
  grid-template-rows: 0fr;
  opacity: 0;
  transition: grid-template-rows 0.5s cubic-bezier(0.65, 0, 0.35, 1),
              opacity 0.4s ease;
}

.faq-reveal-content > * {
  overflow: hidden;
  min-height: 0;
}

.faq-item.active .faq-reveal-content {
  grid-template-rows: 1fr;
  opacity: 1;
}



.faq-item.active .arrow-faq {
  transform: rotate(0deg);
}






.swiper {
  width: 100%;
  overflow: hidden;
}

.swiper-slide {
  flex-shrink: 0;
}

/* Garde les flèches là où tu les as placées */
.swiper-button-prev,
.swiper-button-next {
  position: static !important;
  top: auto !important;
  right: auto !important;
  bottom: auto !important;
  left: auto !important;
  margin: 0 !important;
}

/* Supprime les flèches natives de Swiper */
.swiper-button-prev::after,
.swiper-button-next::after {
  display: none !important;
  content: none !important;
}

.s-nav {
    width: 72px !important;
    height: 52px !important;
    padding-top: 3px;
}

